H.background();
const F = P.F, r = P.r, deg = P.theta;
const ang = deg * Math.PI / 180;
const tau = r * F * Math.sin(ang);
const px = 280, py = 320;
const pxScale = 26;
const ex = px + r * pxScale, ey = py;
H.line(px, py, ex, ey, { color: H.colors.sub, width: 6 });
H.circle(px, py, 9, { fill: H.colors.ink });
H.circle(ex, ey, 6, { fill: H.colors.grid });
const fScale = 8;
const fang = ang;
const fx = ex + F * fScale * Math.cos(fang);
const fy = ey - F * fScale * Math.sin(fang);
H.arrow(ex, ey, fx, fy, { color: H.colors.accent2, width: 3 });
const perpY = ey - F * fScale * Math.sin(fang);
H.line(ex, ey, ex, perpY, { color: H.colors.good, width: 2, dash: [5,4] });
H.text("F sin(theta)", ex + 8, (ey + perpY) / 2, { color: H.colors.good, size: 12 });
const spin = (t % 3) / 3 * Math.PI * (tau >= 0 ? 1 : -1);
const arcR = 40;
const a0 = Math.PI * 0.15;
const arx = px + arcR * Math.cos(a0 + spin);
const ary = py - arcR * Math.sin(a0 + spin);
H.circle(arx, ary, 6, { fill: H.colors.violet });
H.text("r = " + r.toFixed(2) + " m", (px + ex) / 2 - 20, py + 22, { color: H.colors.sub, size: 12 });
H.text("Torque: tau = r F sin(theta)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Only the perpendicular force component F sin(theta) twists the lever", 24, 50, { color: H.colors.sub, size: 13 });
H.text("F = " + F.toFixed(1) + " N   r = " + r.toFixed(2) + " m   theta = " + deg.toFixed(0) + " deg   tau = " + tau.toFixed(2) + " N*m", 24, 72, { color: H.colors.yellow, size: 13 });
